import React from "react";

const Archive = ({ archive, onBack }) => (
  <div className="p-4">
    <h2 className="text-xl font-bold mb-4">Archiwum zadań</h2>
    <ul className="space-y-2">
      {archive.length === 0 && (
        <li className="text-gray-500">Brak zarchiwizowanych zadań</li>
      )}
      {archive.map((task) => (
        <li key={task.id} className="bg-zinc-100 dark:bg-zinc-700 rounded p-2">
          {task.text}
        </li>
      ))}
    </ul>
    <button
      className="mt-4 bg-blue-600 text-white px-4 py-2 rounded"
      onClick={onBack}
    >
      Powrót
    </button>
  </div>
);

export default Archive;
